// Adds a stable request id for easier debugging / support escalation.
const requestId = crypto.randomUUID();

const upstreamRes = await fetch(`${process.env.REDWOOD_BASE_URL}/v1/chat/completions`, {
  method: "POST",
  headers: {
    "Authorization": `Bearer ${process.env.REDWOOD_API_KEY}`,
    "Content-Type": "application/json",
    "x-redwood-request-id": requestId,
    ...(req.headers.get("traceparent") ? { "traceparent": req.headers.get("traceparent")! } : {})
  },
  body: JSON.stringify({
    model: process.env.REDWOOD_MODEL,
    stream: true,
    messages
  })
});

return new Response(upstreamRes.body, {
  status: upstreamRes.status,
  headers: {
    "Content-Type": upstreamRes.headers.get("Content-Type") ?? "text/event-stream",
    "x-redwood-request-id": requestId
  }
});
